            else if (c == '>')
                writeText(output, "&gt;");
            else if (c == '&')
                writeText(output, "&amp;");
            else if (c == '"')
                writeText(output, "&quot;");
            else if (c == '\'')
                writeText(output, "&apos;");
            else if ((c < 32 && c != 9 && c != 10 && c != 13) || c > 126)
            {
                formatter(buffer, "&#%d;", static_cast<int>(c));
                writeText(output, buffer);
            }
            else
                writeChar(output, c);
        } while (--length);
    }
}

